// These bytes were generated by unmodified 4c4d96ab962e8b38a0de312dea224ce2f5466935,
// using its existing installation and interrupted-network fixtures.
func TestHistoricalInstallAndInterruptedJournal(t *testing.T) {
	_, m, app, perl, ast, db := runtimeFixture(t)
	sources := InstallSources{db, ast, app, perl, PhoneSource{files: map[string][]byte{"fixture": []byte("verified fixture")}}}
	raw, err := os.ReadFile("testdata/alm34/legacy-plan.json")
	if err != nil {
		t.Fatal(err)
	}
	digest, _ := os.ReadFile("testdata/alm34/legacy-digest.txt")
	p, err := DecodeInstallPlan(raw, m, sources)
	if err != nil || p.Digest() != string(digest) || !bytes.Equal(p.JSON(), raw) {
		t.Fatal("historical plan identity changed", err, p.Digest())
	}
	d, _ := p.document()
	if d.Request.Authorization.Mode != "" || !d.Request.Authorization.valid(d.Initial.Inventory.Host) {
		t.Fatal("legacy meaning changed")
	}
	standard := d.Request
	standard.Authorization = InstallAuthorization{Mode: StandardAuthorization, Host: d.Initial.Inventory.Host}
	q, err := PrepareInstall(standard, d.Initial, m, sources, d.Certificate)
	if err != nil || q.Digest() == p.Digest() {
		t.Fatal("standard identity", err)
	}
	again, err := DecodeInstallPlan(q.JSON(), m, sources)
	if err != nil || again.Digest() != q.Digest() {
		t.Fatal("standard roundtrip", err)
	}
	// Wrong approvals are rejected before host inspection, TLS, locks or effects.
	for _, approval := range []string{"", p.Digest(), strings.Repeat("0", 64)} {
		state := filepath.Join(t.TempDir(), "uncreated")
		if _, err := ExecuteInstall(context.Background(), q, m, sources, Native{}, state, approval, nil); err == nil {
			t.Fatal("wrong approval accepted")
		}
		if _, err := os.Stat(state); !os.IsNotExist(err) {
			t.Fatal("preapproval mutation")
		}
	}
	input, _ := os.ReadFile("testdata/alm34/legacy-network-input.json")
	var in NetworkInputs
	if err := decode(string(input), &in); err != nil {
		t.Fatal(err)
	}
	stage, err := in.Prepare(m, app, perl, ast, db)
	if err != nil {
		t.Fatal(err)
	}
	oldStage, _ := os.ReadFile("testdata/alm34/legacy-network-stage.json")
	if !bytes.Equal(stage.JSON(), oldStage) {
		t.Fatal("historical stage changed")
	}
	oldJournal, _ := os.ReadFile("testdata/alm34/legacy-network-journal.json")
	old, err := journal.Decode(bytes.NewReader(oldJournal))
	if err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join(t.TempDir(), "state")
	if err := os.Mkdir(dir, 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "journal.json"), oldJournal, 0600); err != nil {
		t.Fatal(err)
	}
	f := &networkFake{s: in.Snapshot}
	// Reproduce the interrupted effect without rerunning the action.
	f.s.Files = hash("files")
	f.s.Services = hash("services")
	f.s.Health = hash("policy health")
	f.s.Current = hash("new effective policy")
	out, err := ExecuteNetworkLab(context.Background(), stage, m, networkAuth(stage), dir, f, f, true, nil)
	if err != nil || f.calls != 0 || out.Journal.Identity != old.Identity || out.Journal.Actions[0].State != journal.Succeeded {
		t.Fatal("historical resume changed identity or replayed effect", err, out)
	}
}

func TestAuthorizationModes(t *testing.T) {
	host := hash("host")
	good := InstallAuthorization{Mode: StandardAuthorization, Host: host}
	if !good.valid(host) {
		t.Fatal("standard needs managed evidence")
	}
	for _, field := range []string{"host", "mode", "task", "snapshot", "evidence", "candidate", "recovery"} {
		a := good
		switch field {
		case "host":
			a.Host = hash("other")
		case "mode":
			a.Mode = "unknown"
		case "task":
			a.TaskID = "internal"
		case "snapshot":
			a.SnapshotReference = hash("fake")
		case "evidence":
			a.OperatorEvidenceSHA256 = hash("fake")
		case "candidate":
			a.CandidateAcknowledged = true
		case "recovery":
			a.ManagementRecoveryVerified = true
		}
		if a.valid(host) {
			t.Fatal("mixed/invalid authority accepted", field)
		}
	}
	for _, scope := range []string{"ALM-16/disposable-lab", "ALM-17/disposable-lab", "ALM-18/disposable-lab", "ALM-19/disposable-lab", "ALM-20/disposable-lab", "ALM-21/disposable-lab", "ALM-23/disposable-lab", "ALM-24/disposable-lab", "ALM-25/disposable-lab", "ALM-26/disposable-lab"} {
		if !stageAuthorization(StandardAuthorization, scope, "", "", false, false, true) {
			t.Fatal(scope)
		}
		if stageAuthorization(scope, scope, "", "", false, false, true) {
			t.Fatal("weakened legacy", scope)
		}
		if !stageAuthorization(scope, scope, hash("snapshot"), hash("authority"), true, true, true) {
			t.Fatal("legacy rejected", scope)
		}
		if stageAuthorization(scope, scope, hash("snapshot"), hash("authority"), true, false, true) {
			t.Fatal("missing legacy recovery", scope)
		}
	}
}
